import { promises as fs } from "fs";
import path from "path";
import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { renderMarkdown } from "@/lib/markdown";

export const dynamic = "force-dynamic";

/**
 * Private, staff-only viewer for the Cyrus documentation set (docs/cyrus/**.md). Same safe in-house Markdown renderer
 * as /admin/docs. Only files that exist under docs/cyrus are ever read (the page id is matched against a directory
 * listing, never joined into a path), so ?p= cannot reach any other file.
 */
const BASE = path.join(process.cwd(), "docs", "cyrus");

async function listPages(dir = "", out: string[] = []): Promise<string[]> {
  for (const e of await fs.readdir(path.join(BASE, dir), { withFileTypes: true })) {
    if (e.name.startsWith("_")) continue;
    const rel = dir ? `${dir}/${e.name}` : e.name;
    if (e.isDirectory()) await listPages(rel, out);
    else if (e.name.endsWith(".md")) out.push(rel.replace(/\.md$/, ""));
  }
  return out;
}

const ORDER = (id: string) => (id === "README" ? "" : id.startsWith("reference/") ? "~" + id : id);

/** Rewrite relative .md links to this viewer; links to anything else in the repo become plain text. */
function rewriteLinks(md: string, current: string, known: Set<string>): string {
  return md.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (m, label: string, href: string) => {
    if (/^(https?:|mailto:|#|\/)/.test(href)) return m;
    const [target] = href.split("#");
    if (!target.endsWith(".md")) return label;
    const id = path.posix.normalize(path.posix.join(path.posix.dirname(current), target)).replace(/\.md$/, "");
    return known.has(id) ? `[${label}](/admin/docs/cyrus?p=${encodeURIComponent(id)})` : label;
  });
}

export default async function AdminCyrusDocs({ searchParams }: { searchParams: Promise<{ p?: string }> }) {
  await requireArea("platform");
  const { p } = await searchParams;

  let pages: string[] = [];
  let error: string | null = null;
  try {
    pages = (await listPages()).sort((a, b) => ORDER(a).localeCompare(ORDER(b)));
  } catch {
    error = "docs/cyrus could not be read from disk.";
  }
  const known = new Set(pages);
  const current = p && known.has(p) ? p : "README";

  let html = "";
  if (!error && known.has(current)) {
    try {
      const raw = await fs.readFile(path.join(BASE, `${current}.md`), "utf8");
      html = renderMarkdown(rewriteLinks(raw, current, known));
    } catch {
      error = `docs/cyrus/${current}.md could not be read.`;
    }
  }

  return (
    <div className="space-y-6">
      <PageHeader title="Cyrus documentation" sub="Internal, living documentation of the Cyrus project. Private to staff.">
        <Badge tone="brand">{pages.length} pages</Badge>
        <Link href="/admin/docs" className="btn-ghost text-sm">Platform docs</Link>
      </PageHeader>
      {error ? (
        <div className="card py-12 text-center text-sm text-red-300">{error}</div>
      ) : (
        <div className="grid gap-6 lg:grid-cols-[16rem_1fr]">
          <nav className="card h-fit space-y-0.5 p-3 text-sm lg:sticky lg:top-20">
            {pages.map((id) => (
              <Link
                key={id}
                href={`/admin/docs/cyrus?p=${encodeURIComponent(id)}`}
                className={`block rounded-lg px-2.5 py-1.5 ${id === current ? "bg-white/[0.08] text-white" : "text-slate-400 hover:bg-white/[0.04] hover:text-slate-200"}`}
              >
function headComment2(rel: string): string {
  const t = rd(rel).split("\n");
  const h = t.find((l) => /^# /.test(l))?.replace(/^# /, "") ?? "";
  return h.slice(0, 160);
}

// ---------- assembly ----------
function gen(title: string, source: string): string {
  return [`# ${title}`, "", `> GENERATED by \`scripts/cyrus/docs-build.ts\`. Do not edit by hand: change the code (or \`docs/cyrus/_data/features.json\`) and re-run \`npx tsx scripts/cyrus/docs-build.ts\`. ${source}`, ""].join("\n");
}

export async function buildAll(): Promise<Record<string, string>> {
  return {
    [`${REF_DIR}/flags-and-env.md`]: flagsPage(),
    [`${REF_DIR}/routes.md`]: routesPage(),
    [`${REF_DIR}/db-tables.md`]: tablesPage(),
    [`${REF_DIR}/versions.md`]: versionsPage(),
    [`${REF_DIR}/adapters.md`]: await adaptersPage(),
    [`${REF_DIR}/openapi.md`]: openapiPage(),
    [`${REF_DIR}/feature-map.md`]: featurePage(),
    [`${REF_DIR}/modules.md`]: modulesPage(),
    [`${REF_DIR}/documentation-index.md`]: docIndexPage(),
    [`${REF_DIR}/scripts.md`]: scriptsPage(),
    [`${REF_DIR}/tests.md`]: testsPage(),
  };
}

async function main() {
  const check = process.argv.includes("--check");
  const pages = await buildAll();
  let stale = 0;
  for (const [rel, content] of Object.entries(pages)) {
    const abs = path.join(ROOT, rel);
    const cur = existsSync(abs) ? readFileSync(abs, "utf8") : null;
    if (cur === content) continue;
    if (check) { stale++; console.error(`STALE ${rel}`); continue; }
    mkdirSync(path.dirname(abs), { recursive: true });
    writeFileSync(abs, content);
    console.log(`wrote ${rel}`);
  }
  if (check) {
    if (stale) { console.error(`${stale} generated page(s) stale: run npx tsx scripts/cyrus/docs-build.ts`); process.exit(1); }
    console.log("docs/cyrus/reference is current");
  }
}

if (process.argv[1] && /docs-build\.ts$/.test(process.argv[1])) {
  main().catch((e) => { console.error(e); process.exit(1); });
}

