#!/usr/bin/env tsx
// Cyrus docs link and citation checker (CZ docs-complete, 2026-10-15). Zero dependencies, read only.
//   npx tsx scripts/cyrus/docs-links.ts            check docs/cyrus/**.md
//   npx tsx scripts/cyrus/docs-links.ts --paths    also verify that backticked repo paths cited in the NUMBERED pages exist
// Checks: every relative markdown link resolves to a file and, for .md targets, to a heading; (with --paths) every
// `code span` that looks like a repo path (starts with a known root and has no placeholder) exists, globs must match
// at least one file. Exit 1 on any finding. The same relative-link rule runs inside test/cyrus-docs-coverage.test.ts.
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";

function findRoot(start: string): string {
  let d = start;
  for (let i = 0; i < 8; i++) {
    if (existsSync(path.join(d, "docs", "cyrus")) && existsSync(path.join(d, "package.json"))) return d;
    const up = path.dirname(d);
    if (up === d) break;
    d = up;
  }
  throw new Error("run from inside the repo");
}
const ROOT = findRoot(process.cwd());
const rd = (rel: string) => readFileSync(path.join(ROOT, rel), "utf8");
const slug = (h: string) => h.trim().toLowerCase().replace(/[`*]/g, "").replace(/[^a-z0-9 _-]/g, "").replace(/ /g, "-");

function docFiles(dir = "docs/cyrus", out: string[] = []): string[] {
  for (const n of readdirSync(path.join(ROOT, dir)).sort()) {
    const p = dir + "/" + n;
    if (statSync(path.join(ROOT, p)).isDirectory()) docFiles(p, out);
    else if (n.endsWith(".md")) out.push(p);
  }
  return out;
}
const anchors = (rel: string) => new Set(rd(rel).split("\n").filter((l) => /^#{1,6} /.test(l)).map((l) => slug(l.replace(/^#{1,6} /, ""))));

const ROOTS = ["lib/", "app/", "components/", "services/", "worker/", "scripts/", "deploy/", "prisma/", "test/", "docs/", "apps/", "tools/", "platform/", "content/", "middleware.ts"];
function allFilesUnder(rel: string, out: string[] = []): string[] {
  const abs = path.join(ROOT, rel);
  if (!existsSync(abs)) return out;
  if (statSync(abs).isFile()) { out.push(rel); return out; }
  for (const n of readdirSync(abs)) { if (n === "node_modules" || n === ".next" || n === ".git") continue; allFilesUnder(rel + "/" + n, out); }
  return out;
}
function globToRe(g: string): RegExp {
  return new RegExp("^" + g.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*\*/g, "\u0000").replace(/\*/g, "[^/]*").replace(/\u0000/g, ".*") + "$");
}
function pathExists(spec: string): boolean {
  const p = spec.replace(/\/+$/, "");
  if (/[*]/.test(p)) {
    const base = p.split("*")[0].replace(/[^/]*$/, "").replace(/\/$/, "");
    const re = globToRe(p);
    return allFilesUnder(base || ".").some((f) => re.test(f));
  }
  return existsSync(path.join(ROOT, p));
}

const bad: string[] = [];
const wantPaths = process.argv.includes("--paths");
for (const f of docFiles()) {
  const text = rd(f).replace(/```[\s\S]*?```/g, "");
  for (const m of text.matchAll(/\[[^\]]*\]\(([^)\s]+)\)/g)) {
    const href = m[1];
    if (/^(https?:|mailto:|\/)/.test(href)) continue;
    const [target, anchor] = href.split("#");
    const abs = target ? path.normalize(path.join(path.dirname(f), target)) : f;
    if (!existsSync(path.join(ROOT, abs))) { bad.push(`${f}: broken link ${href}`); continue; }
    if (anchor && abs.endsWith(".md") && !anchors(abs).has(anchor)) bad.push(`${f}: no heading for ${href}`);
  }
  if (wantPaths && /^docs\/cyrus\/\d\d-.*\.md$/.test(f) && !/\/(11-history|12-gaps)/.test(f)) {
    for (const m of text.matchAll(/`([^`\s]+)`/g)) {
