      if (!ROOTS.some((r) => s.startsWith(r)) || /[<>{}$|]/.test(s) || /\.\.\./.test(s) || /^[a-z]+:\/\//.test(s)) continue;
      if (!/\/|\.(ts|tsx|js|mjs|json|md|sh|sql|yaml|yml|java|py)$/.test(s)) continue;
      if (/#/.test(s)) continue;
      if (!pathExists(s)) bad.push(`${f}: cited path not found ${s}`);
    }
  }
}
if (bad.length) { console.error(bad.join("\n")); console.error(`${bad.length} finding(s)`); process.exit(1); }
console.log(`docs links ok (${docFiles().length} pages${wantPaths ? ", cited paths verified" : ""})`);
E
echo done

