describe("cyrus docs: ownership map (doc-owners.json) stays complete", () => {
  type Rule = { paths: string[]; docs: string[] };
  const owners = JSON.parse(rd("docs/cyrus/_data/doc-owners.json")) as { version: number; rules: Rule[] };
  const globRe = (g: string) => new RegExp("^" + g.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*\*/g, "\u0000").replace(/\*/g, "[^/]*").replace(/\u0000/g, ".*") + "$");
  const treeFiles = ["lib", "app", "components", "services", "worker", "scripts", "deploy", "prisma", "apps", "content"].flatMap((r) => walk(r));

  it("has the agreed schema and every doc it names exists", () => {
    assert.equal(owners.version, 1);
    assert.ok(owners.rules.length >= 10);
    const bad: string[] = [];
    for (const r of owners.rules) {
      assert.ok(Array.isArray(r.paths) && r.paths.length > 0 && Array.isArray(r.docs) && r.docs.length > 0);
      for (const d of r.docs) if (!existsSync(path.join(ROOT, d))) bad.push("missing doc " + d);
    }
    assert.deepEqual(bad, []);
  });

  it("every rule matches at least one real file (no dead globs)", () => {
    const dead: string[] = [];
    for (const r of owners.rules) for (const g of r.paths) if (!treeFiles.some((f) => globRe(g).test(f))) dead.push(g);
    assert.deepEqual(dead, []);
  });

  it("every lib/cyrus module directory and build-service module has an owner page", () => {
    const res = owners.rules.flatMap((r) => r.paths.map(globRe));
    const owned = (f: string) => res.some((re) => re.test(f));
    const miss: string[] = [];
    for (const n of readdirSync(path.join(ROOT, "lib/cyrus"))) {
      const rel = "lib/cyrus/" + n;
      const probe = statSync(path.join(ROOT, rel)).isDirectory() ? treeFiles.find((f) => f.startsWith(rel + "/")) : rel;
      if (probe && !owned(probe)) miss.push(rel);
    }
    for (const n of readdirSync(path.join(ROOT, "services/modbuilder")).filter((x) => /\.(js|mjs)$/.test(x))) if (!owned("services/modbuilder/" + n)) miss.push("services/modbuilder/" + n);
    assert.deepEqual(miss, [], "add these paths to docs/cyrus/_data/doc-owners.json (and update the owning page)");
  });

  it("the complete-set pages and generated references exist and are linked from the README", () => {
    const readme = rd("docs/cyrus/README.md");
    const need = ["20-coverage-matrix.md", "21-infrastructure.md", "22-life-of-a-build.md", "23-build-service.md", "24-techniques-catalogue.md", "25-training-and-knowledge.md", "26-assets-taxonomy.md", "27-games.md", "28-operations-handbook.md", "29-decisions-and-placeholders.md", "30-faq.md", "31-app-and-economy.md", "reference/infra-units.md", "reference/build-service.md", "reference/limits.md", "reference/doc-owners.md"];
    const miss = need.filter((n) => !existsSync(path.join(ROOT, "docs/cyrus", n)) || !readme.includes("(" + n + ")"));
    assert.deepEqual(miss, []);
  });

  it("every Dockerfile-less service module is intentional: each top-level service .js is copied into the image or listed as a tool", () => {
    const ref = REF("build-service");
    const notInImage = [...ref.matchAll(/^\| `([^`]+)` \| \d+ \| \*\*no\*\* \|/gm)].map((m) => m[1]);
    const allowed = new Set(["entrypoint.js"]);
    assert.deepEqual(notInImage.filter((n) => !allowed.has(n)), [], "module not copied by services/modbuilder/Dockerfile: add the COPY or move it under tools/");
  });
});
