function noteFor(notes: Record<string, string>, name: string): string {
  if (notes[name]) return notes[name];
  let best = "";
  for (const k of Object.keys(notes)) if (k.endsWith("*") && name.startsWith(k.slice(0, -1)) && k.length > best.length) best = k;
  return best ? notes[best] : "";
}

